// All tunables in one place. Secrets live in n8n credentials; recipient
// addresses live in the "sprint_digest_recipients" Data Table.
const CONFIG = {
  "jiraBaseUrl": "https://your-team.atlassian.net",
  "boardIds": [],
  "boardTypes": [
    "scrum",
    "simple"
  ],
  "timezone": "Asia/Kolkata",
  "staleInProgressDays": 3,
  "overloadThreshold": 5,
  "blockedStatusNames": [
    "Blocked"
  ],
  "flaggedField": "customfield_10021",
  "storyPointsField": "customfield_10016",
  "criticalBlockedCount": 3,
  "criticalBehindPct": 30,
  "atRiskBehindPct": 15,
  "progressBasis": "both",
  "minPointsCoveragePct": 50,
  "sprintBoardRouting": "all",
  "pageSize": 100,
  "maxPages": 50,
  "jiraMaxRetries": 4,
  "jiraRetryBaseDelayMs": 1000,
  "jiraRetryMaxDelayMs": 30000,
  "jiraPageIntervalMs": 200,
  "fromEmail": "n8n Sprint Digest <sprint-digest@your-domain.com>",
  "staleClaimMinutes": 30,
  "maxListItems": 10
};

// ---- validation (src/validate.js): a bad value stops the run here, before any
// Jira call or email, and the Error Workflow emails the admins the list.
// Validate Config: run by the Config node before anything touches Jira or email,
// and by scripts/build-workflows.js at build time. Pure function, no n8n globals.
//
// Errors stop the run (the Error Workflow then emails the admins with the list),
// warnings are reported in the run summary.

const PLACEHOLDER_HOSTS = ['your-team.atlassian.net', 'your-domain.com', 'example.atlassian.net'];
const BOARD_TYPES = ['scrum', 'simple', 'kanban'];
const FIELD_ID = /^[A-Za-z_][A-Za-z0-9_]*$/; // customfield_10016, duedate, ...
const EMAIL = /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/;

// IANA name -> canonical name, or null if the runtime does not know the zone.
function canonicalTimeZone(tz) {
  if (typeof tz !== 'string' || !tz.trim()) return null;
  // Region/City names (or UTC) only: abbreviations such as IST or EST are ambiguous
  // (IST = India, Israel or Ireland) even where the runtime happens to accept them.
  if (!/^(UTC|GMT|Etc\/[A-Za-z0-9+-]+|[A-Za-z]+(\/[A-Za-z0-9_+-]+)+)$/.test(tz.trim())) return null;
  try {
    return new Intl.DateTimeFormat('en-US', { timeZone: tz.trim() }).resolvedOptions().timeZone;
  } catch (e) {
    return null;
  }
}

// Minimal URL parser: the n8n Code-node sandbox has no global URL class.
function parseUrl(s) {
  const m = /^([a-z][a-z0-9+.-]*:)\/\/(\[[0-9a-f:]+\]|[^/?#:\s[\]]+)(?::(\d{1,5}))?(\/[^?#\s]*)?(\?[^#\s]*)?(#\S*)?$/i.exec(String(s));
  if (!m) return null;
  return { protocol: m[1].toLowerCase(), hostname: m[2].toLowerCase().replace(/^\[|\]$/g, ''), port: m[3] || '', pathname: m[4] || '', search: m[5] || '' };
}

// "Name <addr@x.y>" or "addr@x.y" -> addr@x.y, or null
function emailAddress(s) {
  if (typeof s !== 'string') return null;
  const m = s.match(/<([^<>]+)>\s*$/);
  const addr = (m ? m[1] : s).trim();
  return EMAIL.test(addr) ? addr : null;
}

function validateConfig(cfg, opts = {}) {
  const errors = [];
  const warnings = [];
  const c = cfg || {};

  const int = (key, min, max) => {
    const v = c[key];
    if (v === undefined || v === null || v === '') return errors.push(`${key} is required`);
    if (typeof v !== 'number' || !Number.isInteger(v)) return errors.push(`${key} must be a whole number (got ${JSON.stringify(v)})`);
    if (v < min || (max != null && v > max)) errors.push(`${key} must be between ${min} and ${max == null ? 'any' : max} (got ${v})`);
  };

  // --- Jira site
  if (typeof c.jiraBaseUrl !== 'string' || !c.jiraBaseUrl.trim()) {
    errors.push('jiraBaseUrl is required (e.g. https://your-site.atlassian.net)');
  } else {
    const u = parseUrl(c.jiraBaseUrl.trim());
    if (!u) errors.push(`jiraBaseUrl is not a valid URL (${c.jiraBaseUrl}); expected e.g. https://your-site.atlassian.net`);
    if (u) {
      const local = ['localhost', '127.0.0.1', '::1'].includes(u.hostname);
      if (!['https:', 'http:'].includes(u.protocol)) errors.push('jiraBaseUrl must start with https://');
      else if (u.protocol === 'http:' && !local) warnings.push('jiraBaseUrl uses http://; Jira Cloud requires https://');
      if (PLACEHOLDER_HOSTS.includes(u.hostname)) errors.push(`jiraBaseUrl is still the placeholder (${u.hostname}); set it to your Jira site`);
      if (u.pathname.replace(/\/+$/, '') !== '' || u.search) errors.push('jiraBaseUrl must be the site root only, without a path or query (e.g. https://your-site.atlassian.net)');
    }
  }

  // --- boards
  if (!Array.isArray(c.boardIds)) errors.push('boardIds must be a list of board ids ([] = all boards)');
  else {
    const bad = c.boardIds.filter((b) => !(Number.isInteger(Number(b)) && Number(b) > 0));
    if (bad.length) errors.push(`boardIds contains invalid ids: ${bad.map((b) => JSON.stringify(b)).join(', ')}`);
  }
  if (!Array.isArray(c.boardTypes) || !c.boardTypes.length) errors.push('boardTypes must be a non-empty list (e.g. ["scrum","simple"])');
  else {
    const bad = c.boardTypes.filter((t) => !BOARD_TYPES.includes(String(t)));
    if (bad.length) errors.push(`boardTypes has unknown types: ${bad.join(', ')} (allowed: ${BOARD_TYPES.join(', ')})`);
  }

  // --- timezone (calendar for "today", overdue and the digest date)
  const tz = canonicalTimeZone(c.timezone);
  if (!tz) errors.push(`timezone is not a valid IANA time zone (got ${JSON.stringify(c.timezone)}; e.g. "Asia/Kolkata", not "IST")`);

  // The Schedule trigger fires in the WORKFLOW timezone (Settings -> Timezone, or the
  // instance's GENERIC_TIMEZONE), while the digest logic uses Config.timezone. If they
  // differ, "09:00" and "today" refer to different calendars.
  if (opts.workflowTimezone !== undefined) {
    const wtz = canonicalTimeZone(opts.workflowTimezone);
    if (!opts.workflowTimezone) warnings.push('could not read the workflow timezone; check Settings -> Timezone matches Config.timezone');
    else if (!wtz) errors.push(`workflow timezone ${JSON.stringify(opts.workflowTimezone)} is not a valid IANA time zone`);
    else if (tz && wtz !== tz) {
      errors.push(`workflow timezone is ${opts.workflowTimezone} but Config.timezone is ${c.timezone}; set Workflow Settings -> Timezone to ${c.timezone} (or change Config.timezone) so the schedule and the digest date use the same calendar`);
    }
  }

  // --- business rules
  int('staleInProgressDays', 0, 365);
  int('overloadThreshold', 1, 1000);
  int('criticalBlockedCount', 1, 1000);
  int('criticalBehindPct', 1, 100);
  int('atRiskBehindPct', 1, 100);
  if (Number.isInteger(c.atRiskBehindPct) && Number.isInteger(c.criticalBehindPct) && c.atRiskBehindPct > c.criticalBehindPct) {
    errors.push(`atRiskBehindPct (${c.atRiskBehindPct}) must not be greater than criticalBehindPct (${c.criticalBehindPct})`);
  }
  if (!['issues', 'points', 'both'].includes(c.progressBasis)) errors.push(`progressBasis must be "issues", "points" or "both" (got ${JSON.stringify(c.progressBasis)})`);
  int('minPointsCoveragePct', 0, 100);
  if (['points', 'both'].includes(c.progressBasis) && !c.storyPointsField) warnings.push(`progressBasis is "${c.progressBasis}" but storyPointsField is empty; issue count is used`);
  if (!['all', 'origin'].includes(c.sprintBoardRouting)) errors.push(`sprintBoardRouting must be "all" or "origin" (got ${JSON.stringify(c.sprintBoardRouting)})`);
  if (!Array.isArray(c.blockedStatusNames) || c.blockedStatusNames.some((s) => typeof s !== 'string' || !s.trim())) {
    errors.push('blockedStatusNames must be a list of status names (e.g. ["Blocked"])');
  } else if (!c.blockedStatusNames.length) warnings.push('blockedStatusNames is empty; only the Flagged field and "is blocked by" links mark issues as Blocked');
  for (const key of ['flaggedField', 'storyPointsField']) {
    const v = c[key];
    if (v === undefined || v === null || v === '') { if (key === 'flaggedField') warnings.push('flaggedField is empty; flagged issues will not count as Blocked'); continue; }
    if (typeof v !== 'string' || !FIELD_ID.test(v)) errors.push(`${key} must be a Jira field id like customfield_10016 (got ${JSON.stringify(v)})`);
  }

  // --- Jira API
  int('pageSize', 1, 100); // Jira caps maxResults at 100 for these endpoints
  int('maxPages', 1, 1000);
  int('jiraMaxRetries', 0, 10);
  int('jiraRetryBaseDelayMs', 100, 60000);
  int('jiraRetryMaxDelayMs', 1000, 60000); // >65 s would turn the Wait node into a persisted wait
  int('jiraPageIntervalMs', 0, 10000);
  if (Number.isInteger(c.jiraRetryBaseDelayMs) && Number.isInteger(c.jiraRetryMaxDelayMs) && c.jiraRetryBaseDelayMs > c.jiraRetryMaxDelayMs) {
    errors.push('jiraRetryBaseDelayMs must not be greater than jiraRetryMaxDelayMs');
  }

  // --- delivery
  const from = emailAddress(c.fromEmail);
  if (!from) errors.push(`fromEmail must be an address like "Sprint Digest <digest@your-company.com>" (got ${JSON.stringify(c.fromEmail)})`);
  else if (PLACEHOLDER_HOSTS.includes(from.split('@')[1].toLowerCase())) errors.push(`fromEmail is still the placeholder (${from}); set your sender address`);
  int('staleClaimMinutes', 1, 1440);
  int('maxListItems', 1, 200);

  return { errors, warnings };
}

if (typeof module !== 'undefined' && module.exports) module.exports = { validateConfig, canonicalTimeZone, emailAddress, parseUrl };


// $now is in the WORKFLOW timezone, the one the Schedule trigger fires in.
const workflowTimezone = (typeof $now !== 'undefined' && $now && $now.zoneName) || '';
const check = validateConfig(CONFIG, { workflowTimezone });
if (check.errors.length) {
  throw new Error('Invalid Config (' + check.errors.length + ' problem' + (check.errors.length > 1 ? 's' : '') + '; edit the Config node or Workflow Settings): '
    + check.errors.join(' | '));
}

const input = $input.first().json || {};
const body = input.body || {};
const trigger = input.body !== undefined ? 'webhook' : (input.timestamp || input['Readable date'] ? 'schedule' : 'manual');
const runId = 'run-' + new Date().toISOString().replace(/[-:.TZ]/g, '').slice(0, 14) + '-' + Math.random().toString(36).slice(2, 6);
return [{ json: { ...CONFIG, runId, trigger, workflowTimezone, configWarnings: check.warnings,
  nowIso: new Date().toISOString(), dryRun: body.dryRun === true, force: body.force === true } }];

const jiraSpec = (cfg, path, query, paging, context, failOnError = false) => ({ path, query, paging, context, failOnError,
  cfg: { jiraBaseUrl: cfg.jiraBaseUrl, maxPages: cfg.maxPages, jiraMaxRetries: cfg.jiraMaxRetries,
    jiraRetryBaseDelayMs: cfg.jiraRetryBaseDelayMs, jiraRetryMaxDelayMs: cfg.jiraRetryMaxDelayMs, jiraPageIntervalMs: cfg.jiraPageIntervalMs } });
const cfg = $('Config').first().json;
return [{ json: jiraSpec(cfg, '/rest/agile/1.0/board', { maxResults: cfg.pageSize }, 'startAt', null) }];

const jiraSpec = (cfg, path, query, paging, context, failOnError = false) => ({ path, query, paging, context, failOnError,
  cfg: { jiraBaseUrl: cfg.jiraBaseUrl, maxPages: cfg.maxPages, jiraMaxRetries: cfg.jiraMaxRetries,
    jiraRetryBaseDelayMs: cfg.jiraRetryBaseDelayMs, jiraRetryMaxDelayMs: cfg.jiraRetryMaxDelayMs, jiraPageIntervalMs: cfg.jiraPageIntervalMs } });
const cfg = $('Config').first().json;
const wanted = (cfg.boardIds || []).map(String);
const types = (cfg.boardTypes || ['scrum', 'simple']).map(String);
const boards = [];
for (const page of $input.all()) {
  if (page.json.error) throw new Error('Get Scrum Boards failed: ' + page.json.error.message);
  for (const b of (page.json.values || [])) {
  if (!types.includes(String(b.type))) continue; // e.g. company-managed kanban
  if (!wanted.length || wanted.includes(String(b.id))) boards.push({ boardId: b.id, boardName: b.name, boardType: b.type });
  }
}
if (!boards.length) throw new Error('No sprint-capable boards found (types ' + types.join('/') + (wanted.length ? ', boardIds ' + wanted.join(',') : '') + '). Check the Jira user can browse the project, or fix Config.boardIds / boardTypes.');
// failOnError=false: a team-managed Kanban board answers 400 and Collect Sprints skips it
return boards.map((b) => ({ json: jiraSpec(cfg, '/rest/agile/1.0/board/' + b.boardId + '/sprint',
  { state: 'active', maxResults: cfg.pageSize }, 'startAt', b, false) }));

// One item per active sprint, de-duplicated (a sprint can show on several boards).
// Team-managed Kanban boards report type 'simple' too; Jira answers their sprint
// call with HTTP 400 "does not support sprints". Skip those, fail on anything else.
// A sprint is listed by its origin board AND by every other board whose filter
// includes its issues. Keep one item per sprint but remember all of those boards,
// so recipients of each board are routed correctly (see Analyze Sprints).
const boardNames = new Map($('Select Boards').all().map((i) => [String(i.json.context.boardId), i.json.context.boardName]));
const seen = new Map();
for (const page of $input.all()) {
  const err = page.json.error;
  if (err) {
    if (err.statusCode === 400 || /support sprints/i.test(String(err.message))) continue;
    throw new Error('Get Active Sprints failed: ' + (err.message || JSON.stringify(err)));
  }
  const listedOn = page.json._context || {};
  for (const s of (page.json.values || [])) {
    if (s.state !== 'active') continue;
    if (!seen.has(s.id)) {
      seen.set(s.id, { sprintId: s.id, name: s.name, goal: s.goal || '', startDate: s.startDate, endDate: s.endDate,
        boardId: s.originBoardId || listedOn.boardId || null, boards: [] });
    }
    const e = seen.get(s.id);
    for (const id of [s.originBoardId, listedOn.boardId]) {
      if (id && !e.boards.some((b) => String(b.id) === String(id))) e.boards.push({ id: Number(id), name: boardNames.get(String(id)) || '' });
    }
  }
}
if (!seen.size) return [{ json: { noActiveSprint: true } }];
return [...seen.values()].map((json) => ({ json }));

const cfg = $('Config').first().json;
return [{ json: { runId: cfg.runId, trigger: cfg.trigger, dryRun: cfg.dryRun, finishedAt: new Date().toISOString(),
  timezone: cfg.timezone, workflowTimezone: cfg.workflowTimezone, configWarnings: cfg.configWarnings || [],
  sent: 0, failed: 0, status: 'no_active_sprint', sprints: [] } }];

const jiraSpec = (cfg, path, query, paging, context, failOnError = false) => ({ path, query, paging, context, failOnError,
  cfg: { jiraBaseUrl: cfg.jiraBaseUrl, maxPages: cfg.maxPages, jiraMaxRetries: cfg.jiraMaxRetries,
    jiraRetryBaseDelayMs: cfg.jiraRetryBaseDelayMs, jiraRetryMaxDelayMs: cfg.jiraRetryMaxDelayMs, jiraPageIntervalMs: cfg.jiraPageIntervalMs } });
const cfg = $('Config').first().json;
const fields = ['summary','status','assignee','duedate','priority','issuetype','created','updated','statuscategorychangedate','resolutiondate','issuelinks', cfg.flaggedField, cfg.storyPointsField].filter(Boolean).join(',');
return $input.all().map(({ json: s }) => ({ json: jiraSpec(cfg, '/rest/api/3/search/jql',
  { jql: 'sprint = ' + s.sprintId + ' ORDER BY key', fields, maxResults: cfg.pageSize }, 'nextPageToken', s) }));

// Each response page carries the sprint it was fetched for (_context).
const s = $json._context;
if ($json.error) throw new Error('Get Sprint Issues failed for sprint ' + s.sprintId + ' (' + s.name + '): ' + $json.error.message);
return { json: { sprint: { id: s.sprintId, name: s.name, goal: s.goal, startDate: s.startDate, endDate: s.endDate, boardId: s.boardId, boards: s.boards || [] },
  issues: $json.issues || [] } };

// Analyze Sprints: the core business logic of the Jira Sprint Health Monitor.
// Pure function (no n8n globals) so it can be unit-tested with plain Node and
// inlined into the "Analyze Sprints" Code node by scripts/build-workflows.js.

const DAY_MS = 864e5;

// Jira returns offsets like "+0530"; JS Date wants "+05:30".
function parseJiraDate(s) {
  if (!s) return null;
  const t = Date.parse(String(s).replace(/([+-]\d{2})(\d{2})$/, '$1:$2'));
  return Number.isNaN(t) ? null : t;
}

// Calendar date (YYYY-MM-DD) as seen in the configured timezone.
function localDate(ms, timeZone) {
  return new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' })
    .format(new Date(ms));
}

function daysBetweenDates(a, b) {
  // whole calendar days from date string a to date string b (b - a)
  return Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / DAY_MS);
}

function categoryOf(fields) {
  const key = fields && fields.status && fields.status.statusCategory && fields.status.statusCategory.key;
  if (key === 'done') return 'done';
  if (key === 'indeterminate') return 'inprogress';
  return 'todo';
}

function blockedReason(fields, config) {
  const statusName = ((fields.status && fields.status.name) || '').toLowerCase();
  const names = (config.blockedStatusNames || []).map((s) => String(s).toLowerCase());
  if (names.includes(statusName)) return 'status';
  const flag = config.flaggedField ? fields[config.flaggedField] : null;
  if (flag && (!Array.isArray(flag) || flag.length > 0)) return 'flagged';
  for (const link of fields.issuelinks || []) {
    const inward = link.type && String(link.type.inward || '').toLowerCase();
    const other = link.inwardIssue;
    if (inward === 'is blocked by' && other) {
      const otherCat = other.fields && other.fields.status && other.fields.status.statusCategory
        && other.fields.status.statusCategory.key;
      if (otherCat !== 'done') return 'blocked by ' + other.key;
    }
  }
  return null;
}

function normalizeIssue(raw, ctx) {
  const { config, nowMs, today } = ctx;
  const f = raw.fields || {};
  const category = categoryOf(f);
  const isDone = category === 'done';
  const blocked = isDone ? null : blockedReason(f, config);
  const catChanged = parseJiraDate(f.statuscategorychangedate);
  const inProgressDays = category === 'inprogress' && catChanged != null
    ? (nowMs - catChanged) / DAY_MS : null;
  const due = f.duedate || null; // date-only "YYYY-MM-DD"
  const overdueDays = due && !isDone && due < today ? daysBetweenDates(due, today) : 0;
  const rawPoints = config.storyPointsField ? f[config.storyPointsField] : null;
  const estimated = typeof rawPoints === 'number' && Number.isFinite(rawPoints);
  const points = estimated ? rawPoints : 0;
  return {
    key: raw.key,
    summary: f.summary || '',
    status: (f.status && f.status.name) || 'Unknown',
    category,
    bucket: blocked ? 'Blocked' : ({ todo: 'To Do', inprogress: 'In Progress', done: 'Done' })[category],
    // accountId is the stable identity; display names are not unique (two "Rahul"s)
    assigneeId: f.assignee ? (f.assignee.accountId || f.assignee.displayName || null) : null,
    assignee: f.assignee ? (f.assignee.displayName || f.assignee.accountId) : null,
    priority: (f.priority && f.priority.name) || '',
    due,
    points,
    estimated,
    inProgressDays: inProgressDays == null ? null : Math.round(inProgressDays * 10) / 10,
    flags: {
      stale: inProgressDays != null && inProgressDays > config.staleInProgressDays && !blocked,
      overdue: overdueDays > 0,
      unassigned: !f.assignee && !isDone,
      blocked: !!blocked,
    },
    overdueDays,
    blockedReason: blocked,
  };
}

// Two different people can share a display name. Group by accountId everywhere and,
// only when a name is ambiguous within the sprint, show "Name (…1a2b)" so the
// digest tells them apart.
function labelAssignees(issues) {
  const idsByName = new Map();
  for (const i of issues) {
    if (!i.assigneeId) continue;
    if (!idsByName.has(i.assignee)) idsByName.set(i.assignee, new Set());
    idsByName.get(i.assignee).add(i.assigneeId);
  }
  for (const i of issues) {
    if (i.assigneeId && idsByName.get(i.assignee).size > 1) {
      i.assignee = `${i.assignee} (…${String(i.assigneeId).slice(-4)})`;
    }
  }
}

// Progress used for health: issue count, story points, or the lower of the two.
// Story points only count when enough of the sprint is estimated; otherwise a
// sprint with one 13-point story done would look 90% complete.
function progressOf(m, config) {
  const basis = config.progressBasis || 'both';
  const minCoverage = config.minPointsCoveragePct == null ? 50 : config.minPointsCoveragePct;
  const pointsUsable = m.pointsTotal > 0 && m.pointsCoveragePct >= minCoverage;
  if (basis === 'issues' || !pointsUsable) {
    return { progressPct: m.completionPct, progressBy: 'issues', pointsUsable };
  }
  if (basis === 'points' || m.pointsPct < m.completionPct) {
    return { progressPct: m.pointsPct, progressBy: 'story points', pointsUsable };
  }
  return { progressPct: m.completionPct, progressBy: 'issues', pointsUsable };
}

function healthOf(m, config) {
  const reasons = [];
  if (m.total === 0) return { health: 'Empty', reasons: ['Sprint has no issues'] };
  const progress = m.progressPct == null ? m.completionPct : m.progressPct;
  const behind = m.elapsedPct - progress;
  const behindTxt = `${behind}% behind schedule (by ${m.progressBy || 'issues'})`;
  if (m.blocked >= config.criticalBlockedCount) reasons.push(`${m.blocked} issues blocked`);
  if (behind >= config.criticalBehindPct) reasons.push(behindTxt);
  if (reasons.length) return { health: 'Critical', reasons };
  if (m.blocked > 0) reasons.push(`${m.blocked} blocked`);
  if (m.overdue > 0) reasons.push(`${m.overdue} overdue`);
  if (behind >= config.atRiskBehindPct) reasons.push(behindTxt);
  if (m.overloaded > 0) reasons.push(`${m.overloaded} overloaded member(s)`);
  if (reasons.length) return { health: 'At Risk', reasons };
  return { health: 'Healthy', reasons: ['On track'] };
}

function pct(n, d) { return d > 0 ? Math.round((n / d) * 100) : 0; }

function analyzeSprint(sprint, rawIssues, ctx) {
  const { config, nowMs, today, history, recipients, runId, dryRun, force } = ctx;
  // de-duplicate issues by key (defensive against overlapping pages)
  const seen = new Set();
  const issues = [];
  for (const r of rawIssues) {
    if (!r || !r.key || seen.has(r.key)) continue;
    seen.add(r.key);
    issues.push(normalizeIssue(r, ctx));
  }
  labelAssignees(issues);
  const count = (fn) => issues.filter(fn).length;
  const startMs = parseJiraDate(sprint.startDate);
  const endMs = parseJiraDate(sprint.endDate);
  const elapsedPct = startMs && endMs && endMs > startMs
    ? Math.max(0, Math.min(100, Math.round(((nowMs - startMs) / (endMs - startMs)) * 100))) : 0;
  const daysLeft = endMs ? Math.max(0, Math.ceil((endMs - nowMs) / DAY_MS)) : null;

  // workload per assignee (unresolved only), keyed by accountId, not display name
  const byPerson = {};
  for (const i of issues) {
    if (i.category === 'done' || !i.assigneeId) continue;
    const p = byPerson[i.assigneeId]
      || (byPerson[i.assigneeId] = { accountId: i.assigneeId, name: i.assignee, open: 0, inProgress: 0, blocked: 0, points: 0 });
    p.open += 1;
    if (i.bucket === 'In Progress') p.inProgress += 1;
    if (i.bucket === 'Blocked') p.blocked += 1;
    p.points += i.points;
  }
  const workload = Object.values(byPerson)
    .map((p) => ({ ...p, overloaded: p.open >= config.overloadThreshold }))
    .sort((a, b) => b.open - a.open || a.name.localeCompare(b.name) || a.accountId.localeCompare(b.accountId));

  const m = {
    total: issues.length,
    todo: count((i) => i.bucket === 'To Do'),
    inProgress: count((i) => i.bucket === 'In Progress'),
    done: count((i) => i.bucket === 'Done'),
    blocked: count((i) => i.bucket === 'Blocked'),
    stale: count((i) => i.flags.stale),
    overdue: count((i) => i.flags.overdue),
    unassigned: count((i) => i.flags.unassigned),
    overloaded: workload.filter((p) => p.overloaded).length,
    pointsTotal: issues.reduce((s, i) => s + i.points, 0),
    pointsDone: issues.filter((i) => i.category === 'done').reduce((s, i) => s + i.points, 0),
    estimated: count((i) => i.estimated),
    elapsedPct,
    daysLeft,
  };
  m.completionPct = pct(m.done, m.total);
  m.pointsPct = pct(m.pointsDone, m.pointsTotal);
  m.pointsCoveragePct = pct(m.estimated, m.total);
  Object.assign(m, progressOf(m, config));
  const { health, reasons } = healthOf(m, config);

  // previous sent snapshot for this sprint (strictly before today) -> day-over-day delta
  const digestKey = `${sprint.id}:${today}`;
  const prev = history
    .filter((r) => String(r.sprint_id) === String(sprint.id) && r.status === 'sent' && r.run_date < today)
    .sort((a, b) => (a.run_date < b.run_date ? 1 : -1))[0] || null;
  const delta = prev ? {
    since: prev.run_date,
    completionPct: m.completionPct - Number(prev.completion_pct || 0),
    done: m.done - Number(prev.done || 0),
    blocked: m.blocked - Number(prev.blocked || 0),
    pointsPct: Number(prev.points_total) > 0 && m.pointsTotal > 0
      ? m.pointsPct - pct(Number(prev.points_done || 0), Number(prev.points_total)) : null,
  } : null;

  // dedupe decision against today's rows (the claim step re-checks under race)
  const todays = history.filter((r) => r.digest_key === digestKey);
  const staleClaimMs = config.staleClaimMinutes * 60e3;
  // A sprint can show on several boards (its origin board plus any board whose
  // filter includes its issues). Route to recipients of ANY of those boards, or
  // only the origin board when Config.sprintBoardRouting = 'origin'.
  const boards = (Array.isArray(sprint.boards) && sprint.boards.length)
    ? sprint.boards : (sprint.boardId ? [{ id: sprint.boardId, name: '' }] : []);
  const routeBoards = (config.sprintBoardRouting === 'origin' && sprint.boardId ? [sprint.boardId] : boards.map((b) => b.id))
    .map((id) => String(Number(id)));
  const to = recipients
    .filter((r) => r.active !== false && (r.role || 'digest') === 'digest')
    .filter((r) => !Number(r.board_id) || routeBoards.includes(String(Number(r.board_id))))
    .map((r) => String(r.email).trim()).filter(Boolean);
  const uniqueTo = [...new Set(to)];
  let action = 'send';
  if (!uniqueTo.length) action = 'skip_no_recipients';
  else if (!force && todays.some((r) => r.status === 'sent')) action = 'skip_already_sent';
  else if (!force && todays.some((r) => r.status === 'pending'
    && nowMs - (parseJiraDate(r.claimed_at) || 0) < staleClaimMs)) action = 'skip_in_flight';
  if (dryRun && action === 'send') action = 'preview';

  const lists = {
    blocked: issues.filter((i) => i.flags.blocked),
    stale: issues.filter((i) => i.flags.stale).sort((a, b) => b.inProgressDays - a.inProgressDays),
    overdue: issues.filter((i) => i.flags.overdue).sort((a, b) => b.overdueDays - a.overdueDays),
    unassigned: issues.filter((i) => i.flags.unassigned),
  };

  const d = {
    digest_key: digestKey,
    run_id: runId,
    run_date: today,
    sprint_id: Number(sprint.id),
    sprint_name: sprint.name || `Sprint ${sprint.id}`,
    board_id: Number(sprint.boardId) || 0,
    board_ids: boards.map((b) => Number(b.id)),
    boards,
    sprint_goal: sprint.goal || '',
    sprint_start: sprint.startDate || '',
    sprint_end: sprint.endDate || '',
    health,
    health_reasons: reasons,
    metrics: m,
    workload,
    lists,
    delta,
    recipients: uniqueTo,
    action,
  };
  const email = renderEmail(d, config);
  d.subject = email.subject;
  d.html = email.html;
  d.text = email.text;
  return d;
}

function esc(s) {
  return String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
}

